    // ✅ BACK / EXIT - FIXED - Minimize = Home Page, Exit = App থেকে বের
    @Override public void onBackPressed() { showExitDialog(); }
    private void showExitDialog() {
        AlertDialog.Builder b = new AlertDialog.Builder(this);
        b.setTitle("Exit Room?");
        b.setMessage("Room থেকে বের হবা নাকি Minimize করে Home এ যাবা?");
        b.setPositiveButton("🚪 Exit Room", (d,w) -> {
            // Exit Room = অ্যাপ থেকে বের
            leaveRoomAndFinish();
            finishAffinity();
        });
        b.setNeutralButton("📱 Minimize", (d,w) -> {
            // Minimize = Home Page এ যাবে, অ্যাপের বাইরে না - আগের ভুল ঠিক করা
            leaveRoomKeepHome();
            finish(); // আগের Activity = Home / Room List
        });
        b.setNegativeButton("❌ Cancel", (d,w) -> d.dismiss());
        b.show();
    }
    private void leaveRoomKeepHome(){
        // Home এ গেলে সিট থেকে নামবো, কিন্তু online থেকে পুরা বের হবো না যাতে আবার ঢুকতে পারো
        for(int i=0;i<10;i++){
            final int idx=i;
            databaseReference.child("seats").child("seat_"+idx).addListenerForSingleValueEvent(new ValueEventListener(){
                @Override public void onDataChange(@NonNull DataSnapshot s){ String uid=s.child("userId").getValue(String.class); if(uid!=null && uid.equals(currentUserId)) databaseReference.child("seats").child("seat_"+idx).removeValue(); }
                @Override public void onCancelled(@NonNull DatabaseError e){}
            });
        }
    }
    // ✅ WALLET - LIVE - Sending থেকে কমবে, Receiving এ বাড়বে
    private void listenToMyWallet(){
        if(currentUserId.isEmpty()) return;
        userDatabaseRef.child(currentUserId).addValueEventListener(new ValueEventListener(){
            @Override public void onDataChange(@NonNull DataSnapshot s){
                Long w = s.child("walletCoins").getValue(Long.class);
                if(w==null) w = s.child("coins").getValue(Long.class);
                if(w==null) w = 0L;
                // যদি walletCoins না থাকে, sendingCoins থেকে হিসাব করবো না - wallet আলাদা
                // প্রথমবার wallet 0 হলে, ডেমো কয়েন দিবো না, আসলটা দেখাবে
                myWalletCoins = w;
                if(walletTextInGift!=null) walletTextInGift.setText("🪙 Wallet: "+myWalletCoins+" Coins");
            }
            @Override public void onCancelled(@NonNull DatabaseError e){}
        });
    }
    // Theme - এখন কাজ করবো না, আগের মতো রাখছি, পরে ফটো দিয়ে করবো
    private void setupThemeBackgroundImage() {
        try { ViewGroup root = findViewById(android.R.id.content); if (root==null) return; themeBackgroundImg = new ImageView(this); themeBackgroundImg.setScaleType(ImageView.ScaleType.CENTER_CROP); themeBackgroundImg.setAlpha(0.85f); FrameLayout.LayoutParams lp = new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT); root.addView(themeBackgroundImg, 0); if (root.getChildCount()>1) root.getChildAt(1).bringToFront(); } catch (Exception ignored) {}
    }
    private void applyRoomTheme(String c1, String c2, String fullText, String imageName) {
        try { currentThemeName = fullText; int resId = getResources().getIdentifier(imageName, "drawable", getPackageName()); if (themeBackgroundImg!=null) { if (resId!=0) { themeBackgroundImg.setImageResource(resId); themeBackgroundImg.setVisibility(View.VISIBLE); } else { themeBackgroundImg.setVisibility(View.GONE); View rootView = findViewById(android.R.id.content); if (rootView!=null) { GradientDrawable bg = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, new int[]{Color.parseColor(c1), Color.parseColor(c2)}); rootView.setBackground(bg); } } } } catch (Exception ignored) {}
    }
    private void listenToRoomTheme() { roomMetaRef.addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ String n=s.child("roomTheme").getValue(String.class); String c1=s.child("roomThemeColor1").getValue(String.class); String c2=s.child("roomThemeColor2").getValue(String.class); String img=s.child("roomThemeImage").getValue(String.class); if (n!=null && !n.isEmpty() && c1!=null && c2!=null) applyRoomTheme(c1,c2,n, img!=null?img:"theme_night"); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
    private void showRoomThemeDialog() {
        BottomSheetDialog dialog = new BottomSheetDialog(this, R.style.Theme_Design_BottomSheetDialog);
        LinearLayout root = new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(40,40,40,50);
        GradientDrawable bg = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, new int[]{Color.parseColor("#1B1035"), Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); root.setBackground(bg);
        TextView title=new TextView(this); title.setText("🎨 Room Theme - Coming Soon with Photos"); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(18); title.setTypeface(null, android.graphics.Typeface.BOLD); title.setGravity(Gravity.CENTER); title.setPadding(0,0,0,20); root.addView(title);
        TextView info=new TextView(this); info.setText("Theme নিয়ে পরে কাজ করবো। তুমি নতুন ফটো ডাউনলোড করলে আমি ফটো দিয়ে বসাবো। আপাতত কালার Theme ব্যবহার করো।"); info.setTextColor(Color.WHITE); info.setTextSize(14); info.setGravity(Gravity.CENTER); info.setPadding(0,0,0,20); root.addView(info);
        String[][] themes={{"💑 Couple Sunset Beach","#FF6B35","#2A1B4E","theme_couple"},{"🌊 Beautiful Sea Scene","#001F3F","#0074D9","theme_sea"},{"🏔️ Mountain Beauty","#37474F","#78909C","theme_mountain"},{"🌅 Golden Sunset","#FF5722","#FFD700","theme_sunset"},{"🌙 Night Purple Premium","#1B1035","#0A0518","theme_night"}};
        for(String[] t: themes){ Button btn=new Button(this); btn.setText(t[0]+" - Apply"); btn.setBackgroundColor(Color.parseColor("#FFD700")); btn.setTextColor(Color.BLACK); btn.setOnClickListener(v->{ roomMetaRef.child("roomTheme").setValue(t[0]); roomMetaRef.child("roomThemeColor1").setValue(t[1]); roomMetaRef.child("roomThemeColor2").setValue(t[2]); roomMetaRef.child("roomThemeImage").setValue(t[3]); applyRoomTheme(t[1],t[2],t[0],t[3]); dialog.dismiss(); }); root.addView(btn); }
        dialog.setContentView(root); Window w=dialog.getWindow(); if(w!=null){ w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,1200); w.setGravity(Gravity.BOTTOM); } dialog.show();
    }

    private void showIconToolsDialog(boolean isOwner) {
        BottomSheetDialog dialog = new BottomSheetDialog(this, R.style.Theme_Design_BottomSheetDialog);
        LinearLayout root = new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(35,35,35,45);
        GradientDrawable bg = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, new int[]{Color.parseColor("#1B1035"), Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); root.setBackground(bg);
        TextView title=new TextView(this); title.setText("🛠️ Basic Tools"); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(18); title.setTypeface(null, android.graphics.Typeface.BOLD); title.setPadding(0,0,0,15); root.addView(title);
        GridLayout grid = new GridLayout(this); grid.setColumnCount(4); grid.setUseDefaultMargins(true);
        String[][] basic={{"🔒","Lock off"},{"⚙️","Room set"},{"✏️","Room Edit"},{"🧹","Clear charm"},{"💬","Clear chat"},{"🎙️","Change mic"},{"🎨","Mic Theme"},{"👗","Dress"},{"🍀","Lucky Sound"},{"👥","Voice User"},{"🚪","Kick out record"},{"🏆","Reward Event"}};
        for (String[] it: basic) { LinearLayout cell = makeToolIconCell(it[0], it[1], v -> { dialog.dismiss(); handleToolClick(it[1], isOwner); }); grid.addView(cell); }
        root.addView(grid);
        TextView t2=new TextView(this); t2.setText("✨ Other Tools"); t2.setTextColor(Color.parseColor("#FFD700")); t2.setTextSize(18); t2.setTypeface(null, android.graphics.Typeface.BOLD); t2.setPadding(0,25,0,15); root.addView(t2);
        GridLayout grid2 = new GridLayout(this); grid2.setColumnCount(4); grid2.setUseDefaultMargins(true);
        String[][] other={{"▶️","YouTube Co-watch"},{"🎲","Lucky float"},{"⚔️","Room PK"},{"📡","Broadcast"}};
        for (String[] it: other) { LinearLayout cell = makeToolIconCell(it[0], it[1], v -> { dialog.dismiss(); handleToolClick(it[1], isOwner); }); grid2.addView(cell); }
        root.addView(grid2); dialog.setContentView(root); Window w=dialog.getWindow(); if(w!=null){ w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT, 1400); w.setGravity(Gravity.BOTTOM); } dialog.show();
    }
    private LinearLayout makeToolIconCell(String icon, String label, View.OnClickListener l) { LinearLayout cell=new LinearLayout(this); cell.setOrientation(LinearLayout.VERTICAL); cell.setGravity(Gravity.CENTER); cell.setPadding(10,15,10,15); cell.setOnClickListener(l); GradientDrawable bg=new GradientDrawable(); bg.setColor(Color.parseColor("#2A1B4E")); bg.setCornerRadius(18); cell.setBackground(bg); GridLayout.LayoutParams lp=new GridLayout.LayoutParams(); lp.width=0; lp.height=ViewGroup.LayoutParams.WRAP_CONTENT; lp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f); lp.setMargins(6,6,6,6); cell.setLayoutParams(lp); TextView ic=new TextView(this); ic.setText(icon); ic.setTextSize(26); ic.setGravity(Gravity.CENTER); cell.addView(ic); TextView lb=new TextView(this); lb.setText(label); lb.setTextColor(Color.WHITE); lb.setTextSize(11); lb.setGravity(Gravity.CENTER); lb.setTypeface(null, android.graphics.Typeface.BOLD); cell.addView(lb); return cell; }
    private void handleToolClick(String tool, boolean isOwner) { switch(tool) { case "Lock off": showRoomLockPasswordDialog(); break; case "Room set": if(isOwner) showEditRoomDialog(); else Toast.makeText(this,"Only Owner can edit",Toast.LENGTH_SHORT).show(); break; case "Room Edit": if(isOwner) showEditRoomDialog(); else Toast.makeText(this,"Only Owner",Toast.LENGTH_SHORT).show(); break; case "Clear charm": clearCharm(); break; case "Clear chat": messagesRef.removeValue(); chatMessages.clear(); chatAdapter.notifyDataSetChanged(); Toast.makeText(this,"Chat Cleared",Toast.LENGTH_SHORT).show(); break; case "Change mic": Toast.makeText(this,"Change Mic - Select Seat to Change",Toast.LENGTH_SHORT).show(); break; case "Mic Theme": showRoomThemeDialog(); break; case "Dress": Toast.makeText(this,"Dress - Avatar Frame Coming",Toast.LENGTH_SHORT).show(); break; case "Lucky Sound": Toast.makeText(this,"🍀 Lucky Sound Played",Toast.LENGTH_SHORT).show(); break; case "Voice User": showScrollableOnlineMembersDialog(); break; case "Kick out record": showScrollableOnlineMembersDialog(); break; case "Reward Event": showRewardEventDialog(); break; case "YouTube Co-watch": Toast.makeText(this,"YouTube Co-watch - Paste Link to Watch Together",Toast.LENGTH_LONG).show(); break; case "Lucky float": Toast.makeText(this,"🎲 Lucky Float Started",Toast.LENGTH_SHORT).show(); break; case "Room PK": Toast.makeText(this,"⚔️ Room PK - Challenge Another Room",Toast.LENGTH_SHORT).show(); break; case "Broadcast": Toast.makeText(this,"📡 Broadcast Started",Toast.LENGTH_SHORT).show(); break; } }
    private void clearCharm() { databaseReference.child("seats").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ for(int i=0;i<10;i++) databaseReference.child("seats").child("seat_"+i).child("giftTotal").setValue(0L); Toast.makeText(VoiceRoomActivity.this,"Charm Cleared",Toast.LENGTH_SHORT).show(); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }

