    // ✅ NEW GIFT PANEL - Video Demo অনুযায়ী - 65% Popup, Seat Profile উপরে, Wallet, Category, Quantity
    private void showNewGiftPanel(){
        BottomSheetDialog dialog = new BottomSheetDialog(this, R.style.Theme_Design_BottomSheetDialog);
        LinearLayout root = new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(30,20,30,20);
        GradientDrawable bg = new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, new int[]{Color.parseColor("#1B1035"), Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); root.setBackground(bg);
        // Top Bar - Wallet Live
        LinearLayout topBar = new LinearLayout(this); topBar.setOrientation(LinearLayout.HORIZONTAL); topBar.setGravity(Gravity.CENTER_VERTICAL); topBar.setPadding(0,0,0,12);
        TextView title = new TextView(this); title.setText("🎁 Gift Center"); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(18); title.setTypeface(null, android.graphics.Typeface.BOLD); title.setLayoutParams(new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)); topBar.addView(title);
        walletTextInGift = new TextView(this); walletTextInGift.setText("🪙 Wallet: "+myWalletCoins+" Coins"); walletTextInGift.setTextColor(Color.parseColor("#00E676")); walletTextInGift.setTextSize(14); walletTextInGift.setTypeface(null, android.graphics.Typeface.BOLD); walletTextInGift.setPadding(15,10,15,10); GradientDrawable wBg=new GradientDrawable(); wBg.setColor(Color.parseColor("#2A1B4E")); wBg.setCornerRadius(20); walletTextInGift.setBackground(wBg); topBar.addView(walletTextInGift);
        root.addView(topBar);
        // Selected Target Info
        TextView targetInfo = new TextView(this); targetInfo.setText("To: "+selectedGiftTargetName+"  •  Tap a seat user below to select"); targetInfo.setTextColor(Color.WHITE); targetInfo.setTextSize(13); targetInfo.setGravity(Gravity.CENTER); targetInfo.setPadding(0,0,0,10); root.addView(targetInfo);
        // Seat Users Row - ছোট ছোট প্রোফাইল
        HorizontalScrollView seatScroll = new HorizontalScrollView(this); seatScroll.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 180));
        LinearLayout seatRow = new LinearLayout(this); seatRow.setOrientation(LinearLayout.HORIZONTAL); seatRow.setGravity(Gravity.CENTER_VERTICAL);
        // All Button
        seatRow.addView(makeSeatAvatarView("All", "All", null, targetInfo, true));
        databaseReference.child("seats").addListenerForSingleValueEvent(new ValueEventListener(){
            @Override public void onDataChange(@NonNull DataSnapshot snap){
                for(int i=0;i<10;i++){
                    String k="seat_"+i; if(!snap.hasChild(k)) continue;
                    String n=snap.child(k).child("userName").getValue(String.class);
                    String uid=snap.child(k).child("userId").getValue(String.class);
                    String img=snap.child(k).child("userImage").getValue(String.class);
                    if(n==null||n.isEmpty()||uid==null) continue;
                    seatRow.addView(makeSeatAvatarView(n, uid, img, targetInfo, false));
                }
            } @Override public void onCancelled(@NonNull DatabaseError e){}
        });
        seatScroll.addView(seatRow); root.addView(seatScroll);
        // Category Tabs - Gift, Lucky, CP, Activity, Flag, Exclusive, Bag
        HorizontalScrollView catScroll = new HorizontalScrollView(this); catScroll.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 110));
        LinearLayout catRow = new LinearLayout(this); catRow.setOrientation(LinearLayout.HORIZONTAL);
        String[] cats={"Gift","Lucky","CP","Activity","Flag","Exclusive","Bag"};
        List<Button> catBtns = new ArrayList<>();
        RecyclerView rv = new RecyclerView(this); rv.setLayoutManager(new GridLayoutManager(this, 4)); rv.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 650));
        Runnable refreshGifts = () -> {
            List<GiftModel> list = getGiftsForCategory(giftCategory);
            GiftAdapter ad = new GiftAdapter(list, gift -> { selectedGiftHolder[0]=gift; });
            rv.setAdapter(ad);
            for(Button b: catBtns){ b.setBackgroundColor(b.getText().toString().equals(giftCategory)?Color.parseColor("#FFD700"):Color.parseColor("#2A1B4E")); b.setTextColor(b.getText().toString().equals(giftCategory)?Color.BLACK:Color.WHITE); }
        };
        for(String c: cats){ Button b=new Button(this); b.setText(c); b.setTextSize(12); b.setTypeface(null, android.graphics.Typeface.BOLD); LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT); lp.setMargins(0,0,8,0); b.setLayoutParams(lp); b.setOnClickListener(v->{ giftCategory=c; refreshGifts.run(); }); catRow.addView(b); catBtns.add(b); }
        catScroll.addView(catRow); root.addView(catScroll);
        root.addView(rv);
        // Quantity - 1,3,5,10,7,77,177,777
        TextView qtyLabel = new TextView(this); qtyLabel.setText("Quantity: 1  •  1 চাপলে 1টা, 10 চাপলে 10টা একবারে যাবে"); qtyLabel.setTextColor(Color.parseColor("#FFD700")); qtyLabel.setTextSize(12); qtyLabel.setGravity(Gravity.CENTER); qtyLabel.setPadding(0,10,0,8); root.addView(qtyLabel);
        LinearLayout qtyRow = new LinearLayout(this); qtyRow.setOrientation(LinearLayout.HORIZONTAL); qtyRow.setGravity(Gravity.CENTER);
        int[] qtys={1,3,5,10,7,77,177,777};
        List<Button> qtyBtns = new ArrayList<>();
        for(int q: qtys){ Button qb=new Button(this); qb.setText(String.valueOf(q)); qb.setTextSize(12); qb.setTypeface(null, android.graphics.Typeface.BOLD); LinearLayout.LayoutParams qlp=new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f); qlp.setMargins(3,0,3,0); qb.setLayoutParams(qlp); qb.setOnClickListener(v->{ giftQuantity=q; qtyLabel.setText("Quantity: "+q+"  •  "+q+"টা একবারে যাবে"); for(Button bb: qtyBtns){ bb.setBackgroundColor(bb.getText().toString().equals(String.valueOf(giftQuantity))?Color.parseColor("#FF4081"):Color.parseColor("#2A1B4E")); bb.setTextColor(Color.WHITE); } }); qtyRow.addView(qb); qtyBtns.add(qb); }
        root.addView(qtyRow);
        // Send Button
        Button btnSend = new Button(this); btnSend.setText("🚀 Send Gift"); btnSend.setBackgroundColor(Color.parseColor("#FF4081")); btnSend.setTextColor(Color.WHITE); btnSend.setTypeface(null, android.graphics.Typeface.BOLD); LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 120); bp.setMargins(0,15,0,5); btnSend.setLayoutParams(bp); root.addView(btnSend);
        final GiftModel[] selectedGiftHolder = {getGiftsForCategory("Gift").get(0)};
        refreshGifts.run();
        btnSend.setOnClickListener(v -> {
            if(selectedGiftHolder[0]==null) return;
            String priceStr = selectedGiftHolder[0].getGiftPrice().replaceAll("[^0-9]","");
            long onePrice = priceStr.isEmpty()?100L:Long.parseLong(priceStr);
            long totalCost = onePrice * giftQuantity;
            if(myWalletCoins < totalCost && myWalletCoins>0){
                Toast.makeText(this, "Wallet এ কয়েন কম! Need "+totalCost+", Have "+myWalletCoins, Toast.LENGTH_LONG).show();
                return;
            }
            // Wallet থেকে কমবে - Sending
            userDatabaseRef.child(currentUserId).child("walletCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); long now=(cur!=null?cur:0L)-totalCost; if(now<0) now=0; userDatabaseRef.child(currentUserId).child("walletCoins").setValue(now); } @Override public void onCancelled(@NonNull DatabaseError e){} });
            userDatabaseRef.child(currentUserId).child("sendingCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); userDatabaseRef.child(currentUserId).child("sendingCoins").setValue((cur!=null?cur:0L)+totalCost); } @Override public void onCancelled(@NonNull DatabaseError e){} });
            // Target এ যোগ হবে - Receiving - Auto Exchange
            if(selectedGiftTargetUid.equals("") || selectedGiftTargetUid.equals("All")){
                databaseReference.child("seats").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ for(int i=0;i<10;i++){ String k="seat_"+i; if(snap.hasChild(k)){ Long cur=snap.child(k).child("giftTotal").getValue(Long.class); databaseReference.child("seats").child(k).child("giftTotal").setValue((cur!=null?cur:0L)+totalCost); String sid=snap.child(k).child("userId").getValue(String.class); if(sid!=null && !sid.isEmpty()){ updateReceivingCoinsForUser(sid, totalCost); userDatabaseRef.child(sid).child("walletCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s2){ Long wc=s2.getValue(Long.class); userDatabaseRef.child(sid).child("walletCoins").setValue((wc!=null?wc:0L)+totalCost); } @Override public void onCancelled(@NonNull DatabaseError e){} }); } } } } @Override public void onCancelled(@NonNull DatabaseError e){} });
            } else {
                final String targetUid = selectedGiftTargetUid;
                databaseReference.child("seats").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ for(int i=0;i<10;i++){ String k="seat_"+i; if(snap.hasChild(k) && targetUid.equals(snap.child(k).child("userId").getValue(String.class))){ Long cur=snap.child(k).child("giftTotal").getValue(Long.class); databaseReference.child("seats").child(k).child("giftTotal").setValue((cur!=null?cur:0L)+totalCost); } } } @Override public void onCancelled(@NonNull DatabaseError e){} });
                updateReceivingCoinsForUser(targetUid, totalCost);
                userDatabaseRef.child(targetUid).child("walletCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long wc=s.getValue(Long.class); userDatabaseRef.child(targetUid).child("walletCoins").setValue((wc!=null?wc:0L)+totalCost); } @Override public void onCancelled(@NonNull DatabaseError e){} });
            }
            triggerFlyingGiftAnimation(selectedGiftHolder[0].getGiftName()+" x"+giftQuantity);
            String userName=prefs.getString("USER_NAME","User");
            String msgId=messagesRef.push().getKey(); if(msgId!=null){ Map<String,Object> m=new HashMap<>(); m.put("senderName", getCorrectBadgeIcon(currentUserId)+"🎁 "+userName); m.put("message","sent gift ["+selectedGiftHolder[0].getGiftName()+" x"+giftQuantity+" - "+totalCost+" Coins] to "+selectedGiftTargetName); m.put("timestamp", System.currentTimeMillis()); messagesRef.child(msgId).setValue(m); }
            Toast.makeText(this, "Gift Sent x"+giftQuantity+" to "+selectedGiftTargetName, Toast.LENGTH_SHORT).show();
            dialog.dismiss();
        });
        dialog.setContentView(root);
        Window w=dialog.getWindow(); if(w!=null){ int screenH=getResources().getDisplayMetrics().heightPixels; w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT, (int)(screenH*0.67)); w.setGravity(Gravity.BOTTOM); } // 65-67% Popup - Video অনুযায়ী
        dialog.show();
    }
    private final GiftModel[] selectedGiftHolder = {null};
    private View makeSeatAvatarView(String name, String uid, String imgBase64, TextView targetInfo, boolean isAll){
        LinearLayout col=new LinearLayout(this); col.setOrientation(LinearLayout.VERTICAL); col.setGravity(Gravity.CENTER); col.setPadding(12,8,12,8);
        ImageView av=new ImageView(this); LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(110,110); av.setLayoutParams(ap); av.setScaleType(ImageView.ScaleType.CENTER_CROP);
        if(imgBase64!=null && !imgBase64.isEmpty()){ try{ byte[] b=android.util.Base64.decode(imgBase64, android.util.Base64.DEFAULT); Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length); if(bmp!=null){ RoundedBitmapDrawable d=RoundedBitmapDrawableFactory.create(getResources(), bmp); d.setCircular(true); av.setImageDrawable(d); } else av.setImageResource(android.R.drawable.ic_menu_my_calendar); }catch(Exception e){ av.setImageResource(android.R.drawable.ic_menu_my_calendar); } } else av.setImageResource(android.R.drawable.ic_menu_my_calendar);
        if(isAll) av.setImageResource(android.R.drawable.ic_menu_my_calendar);
        col.addView(av);
        TextView nt=new TextView(this); nt.setText(name.length()>8?name.substring(0,8):name); nt.setTextColor(Color.WHITE); nt.setTextSize(11); nt.setGravity(Gravity.CENTER); col.addView(nt);
        col.setOnClickListener(v->{ selectedGiftTargetUid = isAll?"":uid; selectedGiftTargetName = name; if(targetInfo!=null) targetInfo.setText("To: "+name+"  •  Selected"); Toast.makeText(this, "Selected: "+name, Toast.LENGTH_SHORT).show(); });
        return col;
    }
    private List<GiftModel> getGiftsForCategory(String cat){
        List<GiftModel> list=new ArrayList<>();
        if(cat.equals("Gift")){ list.add(new GiftModel("g1","Rose","20",R.drawable.ic_gift_flower,"Gift")); list.add(new GiftModel("g2","Kiss","66",R.drawable.ic_gift_ring,"Gift")); list.add(new GiftModel("g3","Love","100",R.drawable.ic_gift_diamond,"Gift")); list.add(new GiftModel("g4","Cake","199",R.drawable.ic_gift_car,"Gift")); list.add(new GiftModel("g5","Crown","500",R.drawable.ic_gift_crown,"Gift")); list.add(new GiftModel("g6","Diamond","9999",R.drawable.ic_gift_castle,"Gift")); }
        else if(cat.equals("Lucky")){ list.add(new GiftModel("l1","Lucky Star","20",R.drawable.ic_gift_flower,"Lucky")); list.add(new GiftModel("l2","Lucky 7","77",R.drawable.ic_gift_ring,"Lucky")); list.add(new GiftModel("l3","Lucky Wheel","777",R.drawable.ic_gift_diamond,"Lucky")); }
        else if(cat.equals("CP")){ list.add(new GiftModel("c1","CP Heart","99999",R.drawable.ic_gift_flower,"CP")); list.add(new GiftModel("c2","CP Ring","9999",R.drawable.ic_gift_ring,"CP")); }
        else if(cat.equals("Activity")){ list.add(new GiftModel("a1","Birthday Cake","9999",R.drawable.ic_gift_flower,"Activity")); list.add(new GiftModel("a2","Party","999",R.drawable.ic_gift_car,"Activity")); }
        else if(cat.equals("Flag")){ list.add(new GiftModel("f1","Flag","50",R.drawable.ic_gift_flower,"Flag")); list.add(new GiftModel("f2","Country Flag","100",R.drawable.ic_gift_ring,"Flag")); }
        else if(cat.equals("Exclusive")){ list.add(new GiftModel("e1","Exclusive Dragon","250000",R.drawable.ic_gift_diamond,"Exclusive")); list.add(new GiftModel("e2","Exclusive Crown","1000000",R.drawable.ic_gift_crown,"Exclusive")); }
        else if(cat.equals("Bag")){ list.add(new GiftModel("b1","Gift Bag","500",R.drawable.ic_gift_castle,"Bag")); list.add(new GiftModel("b2","Luxury Bag","5000",R.drawable.ic_gift_car,"Bag")); }
        else { list.add(new GiftModel("g1","White Tiger","50000",R.drawable.ic_gift_flower,"Animal")); }
        return list;
    }

    private void showChatDialog() { final Dialog chatDialog = new Dialog(VoiceRoomActivity.this, R.style.Theme_Design_BottomSheetDialog); chatDialog.requestWindowFeature(Window.FEATURE_NO_TITLE); chatDialog.setContentView(R.layout.dialog_bottom_chat); Window window = chatDialog.getWindow(); if(window!=null){ window.setLayout(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT); window.setGravity(Gravity.BOTTOM); window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_VISIBLE); } EditText inputMsg = chatDialog.findViewById(R.id.editRoomMessage); Button btnSendMsg = chatDialog.findViewById(R.id.btnSendRoomMessage); if(btnSendMsg!=null && inputMsg!=null) btnSendMsg.setOnClickListener(view -> { String message=inputMsg.getText().toString().trim(); String userName=prefs.getString("USER_NAME","User"); if(!message.isEmpty()){ String msgId=messagesRef.push().getKey(); if(msgId!=null){ Map<String,Object> m=new HashMap<>(); m.put("senderName", getCorrectBadgeIcon(currentUserId)+userName); m.put("senderId", currentUserId); m.put("message", message); m.put("timestamp", System.currentTimeMillis()); messagesRef.child(msgId).setValue(m); } inputMsg.setText(""); chatDialog.dismiss(); } }); chatDialog.show(); }
    private void showPremiumRankingDialog() { final Dialog rankDialog = new Dialog(this, android.R.style.Theme_Black_NoTitleBar_Fullscreen); rankDialog.requestWindowFeature(Window.FEATURE_NO_TITLE); rankDialog.setContentView(R.layout.dialog_room_ranking); TextView btnClose = rankDialog.findViewById(R.id.btnCloseRanking); if(btnClose!=null) btnClose.setOnClickListener(v -> rankDialog.dismiss()); Button btnTabDaily = rankDialog.findViewById(R.id.btnTabDaily); Button btnTabWeekly = rankDialog.findViewById(R.id.btnTabWeekly); Button btnTabMonthly = rankDialog.findViewById(R.id.btnTabMonthly); LinearLayout listContainer = rankDialog.findViewById(R.id.rankingListContainer); LinearLayout premiumTop = new LinearLayout(this); premiumTop.setOrientation(LinearLayout.HORIZONTAL); premiumTop.setGravity(Gravity.CENTER); premiumTop.setPadding(0,20,0,10); Button btnWealth=new Button(this); btnWealth.setText("💰 Wealth"); Button btnCharm=new Button(this); btnCharm.setText("❤️ Charm"); premiumTop.addView(btnWealth); premiumTop.addView(btnCharm); Runnable loadRank = () -> { btnWealth.setBackgroundColor(rankTab.equals("Wealth")?Color.parseColor("#FFD700"):Color.parseColor("#2A1B4E")); btnWealth.setTextColor(rankTab.equals("Wealth")?Color.BLACK:Color.WHITE); btnCharm.setBackgroundColor(rankTab.equals("Charm")?Color.parseColor("#FF4081"):Color.parseColor("#2A1B4E")); btnCharm.setTextColor(Color.WHITE); userDatabaseRef.orderByChild(rankTab.equals("Wealth")?"sendingCoins":"receivingCoins").limitToLast(20).addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ rankCache.clear(); for(DataSnapshot ds: snap.getChildren()){ String n=ds.child("name").getValue(String.class); Long c=ds.child(rankTab.equals("Wealth")?"sendingCoins":"receivingCoins").getValue(Long.class); String img=ds.child("profileImage").getValue(String.class); if(n==null) n="User"; rankCache.add(new RankItem(n,c!=null?c:0L,img,ds.getKey())); } Collections.sort(rankCache,(a,b)->Long.compare(b.coins,a.coins)); if(listContainer!=null){ listContainer.removeAllViews(); if(rankCache.size()>=3){ LinearLayout podium=new LinearLayout(VoiceRoomActivity.this); podium.setOrientation(LinearLayout.HORIZONTAL); podium.setGravity(Gravity.BOTTOM|Gravity.CENTER); podium.setPadding(0,10,0,15); podium.addView(makePodiumItem(rankCache.get(1),"🥈 Top 2",false)); podium.addView(makePodiumItem(rankCache.get(0),"👑 Top 1",true)); podium.addView(makePodiumItem(rankCache.get(2),"🥉 Top 3",false)); listContainer.addView(podium); } for(int i=0;i<rankCache.size();i++){ String badge=i==0?"#FFD700":i==1?"#C0C0C0":i==2?"#CD7F32":"#FFFFFF"; String label=i<3?"🏆 Top "+(i+1)+" • "+rankCache.get(i).name:(i+1)+". "+rankCache.get(i).name; addRankUserRow(listContainer,String.valueOf(i+1),label,rankCache.get(i).coins+" Coins",badge); } if(rankCache.isEmpty()) addRankUserRow(listContainer,"1","No Ranking Yet - Send Gift to Rank Up","0 Coins","#FFD700"); } } @Override public void onCancelled(@NonNull DatabaseError e){} }); }; btnWealth.setOnClickListener(v->{ rankTab="Wealth"; loadRank.run(); }); btnCharm.setOnClickListener(v->{ rankTab="Charm"; loadRank.run(); }); if(btnTabDaily!=null) btnTabDaily.setOnClickListener(v->{ rankPeriod="Day"; loadRank.run(); }); if(btnTabWeekly!=null) btnTabWeekly.setOnClickListener(v->{ rankPeriod="Week"; loadRank.run(); }); if(btnTabMonthly!=null) btnTabMonthly.setOnClickListener(v->{ rankPeriod="Month"; loadRank.run(); }); try{ ViewGroup parent=(ViewGroup)listContainer.getParent(); parent.addView(premiumTop,0); }catch(Exception ignored){} loadRank.run(); rankDialog.show(); }
    private LinearLayout makePodiumItem(RankItem item, String topText, boolean isTop1){ LinearLayout box=new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); box.setGravity(Gravity.CENTER); box.setLayoutParams(new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f)); TextView crown=new TextView(this); crown.setText(isTop1?"👑":""); crown.setTextSize(22); crown.setGravity(Gravity.CENTER); box.addView(crown); ImageView avatar=new ImageView(this); LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(isTop1?170:130,isTop1?170:130); ap.gravity=Gravity.CENTER; avatar.setLayoutParams(ap); if(item.image!=null && !item.image.isEmpty()){ try{ byte[] b=android.util.Base64.decode(item.image,android.util.Base64.DEFAULT); Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length); if(bmp!=null){ RoundedBitmapDrawable d=RoundedBitmapDrawableFactory.create(getResources(),bmp); d.setCircular(true); avatar.setImageDrawable(d); } }catch(Exception e){ avatar.setImageResource(android.R.drawable.ic_menu_my_calendar); } } else avatar.setImageResource(android.R.drawable.ic_menu_my_calendar); box.addView(avatar); TextView top=new TextView(this); top.setText(topText); top.setTextColor(isTop1?Color.parseColor("#FFD700"):Color.WHITE); top.setTypeface(null,android.graphics.Typeface.BOLD); top.setTextSize(isTop1?15:12); top.setGravity(Gravity.CENTER); if(isTop1) top.setBackgroundColor(Color.parseColor("#B71C1C")); box.addView(top); TextView n=new TextView(this); n.setText(item.name); n.setTextColor(Color.WHITE); n.setTextSize(12); n.setGravity(Gravity.CENTER); box.addView(n); TextView c=new TextView(this); c.setText("🪙 "+item.coins); c.setTextColor(Color.parseColor("#FFD700")); c.setTextSize(11); c.setGravity(Gravity.CENTER); box.addView(c); return box; }
    private void addRankUserRow(LinearLayout container, String rank, String name, String score, String badgeColorHex){ Context ctx=container.getContext(); LinearLayout row=new LinearLayout(ctx); row.setOrientation(LinearLayout.HORIZONTAL); row.setPadding(20,20,20,20); row.setGravity(Gravity.CENTER_VERTICAL); GradientDrawable rBg=new GradientDrawable(); rBg.setColor(Color.parseColor("#1B1035")); rBg.setCornerRadius(16); row.setBackground(rBg); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT); p.setMargins(0,0,0,12); row.setLayoutParams(p); TextView rankTxt=new TextView(ctx); rankTxt.setText("Top "+rank); rankTxt.setTextColor(Color.parseColor(badgeColorHex)); rankTxt.setTextSize(14); rankTxt.setTypeface(null,android.graphics.Typeface.BOLD); rankTxt.setMinWidth(90); row.addView(rankTxt); LinearLayout stack=new LinearLayout(ctx); stack.setOrientation(LinearLayout.VERTICAL); stack.setLayoutParams(new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1.0f)); TextView nameTxt=new TextView(ctx); nameTxt.setText(name); nameTxt.setTextColor(Color.WHITE); nameTxt.setTextSize(15); stack.addView(nameTxt); TextView scoreTxt=new TextView(ctx); scoreTxt.setText(score); scoreTxt.setTextColor(Color.parseColor("#00E676")); scoreTxt.setTextSize(12); stack.addView(scoreTxt); row.addView(stack); container.addView(row); }
    static class RankItem{ String name; long coins; String image; String uid; RankItem(String n,long c,String i,String u){ name=n; coins=c; image=i; uid=u; } }
    private void updateReceivingCoinsForUser(String uid,long c){ userDatabaseRef.child(uid).child("receivingCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); userDatabaseRef.child(uid).child("receivingCoins").setValue((cur!=null?cur:0L)+c); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
    private void triggerFlyingGiftAnimation(String giftName){ try{ ViewGroup rootView=findViewById(android.R.id.content); if(rootView==null) return; final TextView fv=new TextView(this); fv.setText("🎁 "+giftName+" 🚀"); fv.setTextColor(Color.parseColor("#FFD700")); fv.setTextSize(20); fv.setTypeface(null,android.graphics.Typeface.BOLD); fv.setGravity(Gravity.CENTER); fv.setBackgroundColor(Color.parseColor("#88000000")); fv.setPadding(30,20,30,20); FrameLayout.LayoutParams params=new FrameLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,ViewGroup.LayoutParams.WRAP_CONTENT); params.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL; params.setMargins(0,0,0,300); rootView.addView(fv,params); TranslateAnimation anim=new TranslateAnimation(Animation.ABSOLUTE,0f,Animation.ABSOLUTE,0f,Animation.ABSOLUTE,0f,Animation.ABSOLUTE,-1000f); anim.setDuration(2000); anim.setFillAfter(true); anim.setAnimationListener(new Animation.AnimationListener(){ @Override public void onAnimationStart(Animation a){} @Override public void onAnimationEnd(Animation a){ rootView.removeView(fv);} @Override public void onAnimationRepeat(Animation a){} }); fv.startAnimation(anim); }catch(Exception ignored){} }
    private void listenToRoomAdmins(){ adminsRef.addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ roomAdminList.clear(); for(DataSnapshot ds:s.getChildren()) if(Boolean.TRUE.equals(ds.getValue(Boolean.class))) roomAdminList.add(ds.getKey()); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
    private String getCorrectBadgeIcon(String uid){ if(uid==null||uid.isEmpty()) return ""; if(uid.equals(roomOwnerId)||roomAdminList.contains(uid)) return "🛡️ "; return ""; }
    private void listenToRealtimeChatMessages(){ messagesRef.addChildEventListener(new ChildEventListener(){ @Override public void onChildAdded(@NonNull DataSnapshot snap,@Nullable String prev){ String sn=snap.child("senderName").getValue(String.class); String msg=snap.child("message").getValue(String.class); Long t=snap.child("timestamp").getValue(Long.class); if(t!=null && t<roomJoinTimestamp) return; if(sn!=null && msg!=null){ String full=sn+": "+msg; if(!chatMessages.contains(full)){ chatMessages.add(full); chatAdapter.notifyDataSetChanged(); if(chatListView!=null) chatListView.setSelection(chatMessages.size()-1); } } } @Override public void onChildChanged(@NonNull DataSnapshot s,@Nullable String p){} @Override public void onChildRemoved(@NonNull DataSnapshot s){ chatMessages.clear(); chatAdapter.notifyDataSetChanged(); } @Override public void onChildMoved(@NonNull DataSnapshot s,@Nullable String p){} @Override public void onCancelled(@NonNull DatabaseError e){} }); }
    private void showRoomLockPasswordDialog(){ AlertDialog.Builder b=new AlertDialog.Builder(VoiceRoomActivity.this); b.setTitle("🔒 Room Lock Protection"); LinearLayout layout=new LinearLayout(VoiceRoomActivity.this); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(50,30,50,30); final EditText input=new EditText(VoiceRoomActivity.this); input.setHint("Enter Room Password..."); input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD); layout.addView(input); b.setView(layout); b.setPositiveButton("Lock Room",(d,w)->{ String pw=input.getText().toString().trim(); if(!pw.isEmpty()){ roomMetaRef.child("roomPassword").setValue(pw); roomMetaRef.child("isLocked").setValue(true); Toast.makeText(this,"Room locked!",Toast.LENGTH_SHORT).show(); } }); b.setNeutralButton("Unlock Room",(d,w)->{ roomMetaRef.child("roomPassword").removeValue(); roomMetaRef.child("isLocked").setValue(false); Toast.makeText(this,"Room Unlocked!",Toast.LENGTH_SHORT).show(); }); b.setNegativeButton("Cancel",(d,w)->d.cancel()); b.show(); }
